+            let stream = async_stream::stream! {
+                match first_rx.await {
+                    Ok((first, mut tail)) => {
+                        if let Some(first) = first {
+                            yield first;
+                        }
+                        while let Some(item) = tail.next().await {
+                            yield item;
+                        }
+                    }
+                    Err(_) => {
